create or replace function public.painel_geo_arvore(de timestamptz, ate timestamptz) returns table ( pais text, regiao text, cidade text, visitantes bigint, aprovadas bigint, receita numeric ) language sql stable set search_path = '' as $$ with v as ( select geo_country as pais, geo_region as regiao, geo_city as cidade, count(*) as total from public.visitors where created_at >= de and created_at < ate and geo_country is not null group by 1, 2, 3 ), c as ( select geo_country as pais, geo_region as regiao, geo_city as cidade, count(*) as pedidos, coalesce(sum(value), 0) as receita from public.purchases where created_at >= de and created_at < ate and geo_country is not null and status = 'aprovada' group by 1, 2, 3 ) select coalesce(v.pais, c.pais), coalesce(v.regiao, c.regiao), coalesce(v.cidade, c.cidade), coalesce(v.total, 0), coalesce(c.pedidos, 0), coalesce(c.receita, 0) from v full outer join c on c.pais = v.pais and c.regiao is not distinct from v.regiao and c.cidade is not distinct from v.cidade order by 6 desc, 4 desc; $$;
comment on function public.painel_geo_arvore(timestamptz, timestamptz) is 'Geo no grão mais fino, com região e cidade nulas preservadas. Os níveis de cima somam a partir daqui, então fecham por construção.'; revoke all on function public.painel_geo_arvore(timestamptz, timestamptz) from public, anon; grant execute on function public.painel_geo_arvore(timestamptz, timestamptz) to authenticated; create index if not exists visitors_geo_arvore_idx on public.visitors (created_at, geo_country, geo_region, geo_city); drop function if exists public.painel_cidades(timestamptz, timestamptz, integer); drop function if exists public.painel_cidades(timestamptz, timestamptz); drop function if exists public.painel_geo(timestamptz, timestamptz); drop index if exists public.visitors_geo_city_idx;
